// GENERATED by nodered/tools/generate.py from the AquaClean bridge. Edit the settings in the inject node.
// Apply settings: reads the "Settings" inject, keeps them in flow context and (re)subscribes the MQTT in node.
// Change the settings in the inject node "Settings", not here.
const defaults = {
    topicPrefix: "aquaclean",        // the bridge's MQTT topic prefix (field "MQTT topic prefix" on its web page)
    discoveryPrefix: "homeassistant", // the discovery prefix (the shared convention; rarely changed)
    language: "auto",                // language of labels and messages: "auto" or a code such as "en", "nl", "ja"
    allowSharedWrites: false,        // see the README: shared MQTT topics of the user profiles
    onlyChanges: true,               // send a state only when its value changed
    contextName: "aquaclean"         // name of the global context object with every state
};
const cfg = Object.assign({}, defaults, (typeof msg.payload === "object" && msg.payload) || {});
cfg.topicPrefix = String(cfg.topicPrefix).replace(/^\/+|\/+$/g, "");
cfg.discoveryPrefix = String(cfg.discoveryPrefix).replace(/^\/+|\/+$/g, "");
const T = global.get("aquaclean_tables");
if (cfg.language !== "auto" && T && !T.ui[cfg.language]) {
    node.warn(`language "${cfg.language}" is not available, using "auto". Available: ${Object.keys(T.ui).join(", ")}`);
    cfg.language = "auto";
}
flow.set("aquaclean_config", cfg);
// start clean: learned topics and the state of the previous deploy
flow.set("aquaclean_learn", { byKey: {}, disc: {}, lang: null });
global.set(cfg.contextName, { online: null, state: {}, label: {}, updated: {} });
node.status({ fill: "blue", shape: "dot", text: `${cfg.topicPrefix}/# · ${cfg.language}` });
return [[
    { action: "unsubscribe", topic: true },
    { action: "subscribe", topic: [
        { topic: `${cfg.topicPrefix}/#`, qos: 0 },
        { topic: `${cfg.discoveryPrefix}/+/+/+/config`, qos: 0 }
    ] }
]];

// GENERATED by nodered/tools/generate.py from the AquaClean bridge. Edit the settings in the inject node.
// --- shared helpers (the same in Decode and Encode) ---
const T = global.get("aquaclean_tables");
const C = flow.get("aquaclean_config");
const LEARN = flow.get("aquaclean_learn") || { byKey: {}, disc: {}, lang: null };

// language of labels and messages
function uiLang() {
    return C.language === "auto" ? (LEARN.lang || "en") : C.language;
}
// a text of the flow itself, in the chosen language
function t(id, vars) {
    const table = T.ui[uiLang()] || T.ui.en;
    let s = table[T.uiKeys.indexOf(id)] || T.ui.en[T.uiKeys.indexOf(id)];
    for (const [k, v] of Object.entries(vars || {})) s = s.split(`{${k}}`).join(String(v));
    return s;
}
// FNV-1a of "<component>/<object id>": the key of the topic table (same hash as tools/generate.py)
function topicHash(s) {
    let h = 0x811c9dc5;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
    return h.toString(36);
}
function keyOf(component, objectId) {
    const i = T.topics[topicHash(`${component}/${objectId}`)];
    return i === undefined ? null : T.keys[i];
}
// option lists of an entity in one language (with fallback for languages without a list)
function optionList(group, lang) {
    const g = T.options[group];
    return g && (g[lang] || g[T.fallback[lang]] || g.en);
}
// index of an option label in any language; remembers the bridge language when it is unambiguous
function optionIndex(e, label) {
    const groups = e.o || [];
    const order = LEARN.lang ? [LEARN.lang] : [];
    if (label === "") return null;
    for (const g of groups) {
        // bridge languages first (they can be the bridge's own), then the extra Node-RED languages
        for (const lang of order.concat(T.languages, Object.keys(T.options[g]))) {
            const list = T.options[g][lang];
            const i = list ? list.indexOf(label) : -1;
            if (i >= 0) {
                if (!LEARN.lang) {
                    const langs = T.languages.filter(l => T.options[g][l] && T.options[g][l].indexOf(label) === i);
                    if (langs.length === 1) LEARN.lang = langs[0];
                }
                return { index: i, group: g };
            }
        }
    }
    return null;
}

// Decode: turns the bridge's MQTT messages into one message per entity.
//   msg.topic   = the entity key, the same in every language (e.g. "shower_active", "water_temperature")
//   msg.payload = the value: true/false, a number, a text, or for selections the option number (0, 1, 2, ...)
//   msg.aquaclean = { key, group, kind, name, label, unit, shared, known, mqtt, raw }
// Output 1: every state   Output 2: remote control buttons   Output 3: connection and alarms
if (!T || !C) return null;
const P = C.topicPrefix, D = C.discoveryPrefix;
const S = global.get(C.contextName) || { online: null, state: {}, label: {}, updated: {} };
const raw = msg.payload === undefined || msg.payload === null ? "" : String(msg.payload);
const ALARMS = ["connected", "toilet_problem", "bridge_problem", "bridge_health"];

function status() {
    if (S.online === false) node.status({ fill: "red", shape: "ring", text: t("st_offline") });
    else if (S.online === true) node.status({ fill: "green", shape: "dot", text: t("st_online", { n: Object.keys(S.state).length }) });
    else node.status({ fill: "yellow", shape: "ring", text: t("st_wait") });
}
function save() { flow.set("aquaclean_learn", LEARN); global.set(C.contextName, S); }

// 1. availability: <prefix>/status is "online" or "offline"
if (msg.topic === `${P}/status`) {
    S.online = raw === "online";
    save(); status();
    return [null, null, { topic: "online", payload: S.online, aquaclean: { key: "online", group: "bridge", mqtt: msg.topic, raw } }];
}

// 2. discovery: <discovery prefix>/<component>/<node>/<object id>/config, only the bridge's own entities
if (msg.topic.startsWith(`${D}/`) && msg.topic.endsWith("/config")) {
    const parts = msg.topic.split("/");
    if (parts.length !== 5 || raw === "") return null;
    let cfg;
    try { cfg = JSON.parse(raw); } catch (err) { return null; }
    const st = cfg.state_topic || cfg["~"] || cfg.command_topic || "";
    if (!String(st).startsWith(`${P}/`)) return null;
    const base = `${P}/${parts[1]}/${parts[3]}`;
    LEARN.disc[base] = {
        name: cfg.name, options: cfg.options, min: cfg.min, max: cfg.max, step: cfg.step,
        unit: cfg.unit_of_measurement, device: cfg.device && cfg.device.name
    };
    const key = keyOf(parts[1], parts[3]);
    if (key) LEARN.byKey[key] = base;
    save();
    return null;
}

// 3. states: <prefix>/<component>/<object id>/state
if (!msg.topic.startsWith(`${P}/`) || !msg.topic.endsWith("/state")) return null;
const rest = msg.topic.slice(P.length + 1).split("/");
if (rest.length !== 3) return null;
const [component, objectId] = rest;
const base = `${P}/${component}/${objectId}`;
const key = keyOf(component, objectId);
const e = key ? T.e[key] : null;
const disc = LEARN.disc[base] || {};
if (key) LEARN.byKey[key] = base;

let value = raw, label, index, json = null;
try { if (raw.startsWith("{")) json = JSON.parse(raw); } catch (err) { json = null; }
switch (component) {
    case "binary_sensor":
    case "switch":
        value = raw === "ON" ? true : raw === "OFF" ? false : null;
        break;
    case "light":
        value = json && json.state ? json.state === "ON" : null;
        break;
    case "sensor":
    case "number": {
        const n = parseFloat(raw);
        value = Number.isFinite(n) ? n : null;
        if (value !== null && e && e.ts) value = value * 1000;  // timestamp in seconds -> ms (JavaScript time)
        break;
    }
    case "time":
        value = json ? `${String(json.hour).padStart(2, "0")}:${String(json.minute).padStart(2, "0")}` : raw;
        break;
    case "event":
        value = json ? json.event_type : raw;
        break;
    default:  // text_sensor, select, text
        value = raw;
}
if (e && e.ts === "iso" && value) value = Date.parse(value) || null;  // moment of connecting -> ms
if (e && e.o && typeof value === "string") {  // selections and status texts -> option number
    const hit = optionIndex(e, value);
    if (hit) {
        index = hit.index;
        label = (optionList(hit.group, uiLang()) || [])[index] || value;
        value = index;
    }
} else if (component === "select") {
    label = value;  // e.g. the time zone: no fixed list, the text itself
}
if (component === "event" && e) {
    const btn = String(value).replace(/_long$/, "");
    const lang = T.buttons[uiLang()] ? uiLang() : (T.fallback[uiLang()] || "en");
    const b = T.buttons[lang];
    label = (b.names[btn] || btn) + (String(value).endsWith("_long") ? ` (${b.states[1]})` : "");
}

const id = key || `unknown/${component}/${objectId}`;
const changed = JSON.stringify(S.state[id]) !== JSON.stringify(value);
S.state[id] = value;
if (label !== undefined) S.label[id] = label;
S.updated[id] = Date.now();
if (S.online === null) S.online = true;  // states arrive: the bridge is there
save(); status();
if (C.onlyChanges && !changed && component !== "event") return null;

const out = {
    topic: id,
    payload: value,
    aquaclean: {
        key: id, known: !!e, group: e ? e.g : null, kind: component,
        name: disc.name || null, label, unit: disc.unit || (e && e.u) || null,
        shared: !!(e && (e.sh || e.pa)), mqtt: msg.topic, raw
    }
};
if (component === "event") return [out, out, null];
return [out, null, ALARMS.includes(id) ? out : null];

// GENERATED by nodered/tools/generate.py from the AquaClean bridge. Edit the settings in the inject node.
// --- shared helpers (the same in Decode and Encode) ---
const T = global.get("aquaclean_tables");
const C = flow.get("aquaclean_config");
const LEARN = flow.get("aquaclean_learn") || { byKey: {}, disc: {}, lang: null };

// language of labels and messages
function uiLang() {
    return C.language === "auto" ? (LEARN.lang || "en") : C.language;
}
// a text of the flow itself, in the chosen language
function t(id, vars) {
    const table = T.ui[uiLang()] || T.ui.en;
    let s = table[T.uiKeys.indexOf(id)] || T.ui.en[T.uiKeys.indexOf(id)];
    for (const [k, v] of Object.entries(vars || {})) s = s.split(`{${k}}`).join(String(v));
    return s;
}
// FNV-1a of "<component>/<object id>": the key of the topic table (same hash as tools/generate.py)
function topicHash(s) {
    let h = 0x811c9dc5;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
    return h.toString(36);
}
function keyOf(component, objectId) {
    const i = T.topics[topicHash(`${component}/${objectId}`)];
    return i === undefined ? null : T.keys[i];
}
// option lists of an entity in one language (with fallback for languages without a list)
function optionList(group, lang) {
    const g = T.options[group];
    return g && (g[lang] || g[T.fallback[lang]] || g.en);
}
// index of an option label in any language; remembers the bridge language when it is unambiguous
function optionIndex(e, label) {
    const groups = e.o || [];
    const order = LEARN.lang ? [LEARN.lang] : [];
    if (label === "") return null;
    for (const g of groups) {
        // bridge languages first (they can be the bridge's own), then the extra Node-RED languages
        for (const lang of order.concat(T.languages, Object.keys(T.options[g]))) {
            const list = T.options[g][lang];
            const i = list ? list.indexOf(label) : -1;
            if (i >= 0) {
                if (!LEARN.lang) {
                    const langs = T.languages.filter(l => T.options[g][l] && T.options[g][l].indexOf(label) === i);
                    if (langs.length === 1) LEARN.lang = langs[0];
                }
                return { index: i, group: g };
            }
        }
    }
    return null;
}

// Encode: a command for the bridge -> the right MQTT topic and payload.
//   msg.topic   = the entity key (e.g. "shower_toggle", "orientation_light", "light_color")
//   msg.payload = the new value:
//                 buttons: anything            switches, light: true / false / "toggle"
//                 numbers: a number            selections: option number (0, 1, ...) or its text in any language
//                 times: "HH:MM"               texts: a text
// Errors go to node.error, so a Catch node can handle them.
if (!T || !C) return null;
const key = String(msg.topic || "");
const e = T.e[key];
function fail(id, vars) {
    const text = t(id, Object.assign({ key }, vars || {}));
    node.status({ fill: "red", shape: "dot", text });
    node.error(text, msg);
    return null;
}
if (!e) return fail("err_unknown");
if (e.pa) return fail("err_profile");
if (!e.w) return fail("err_readonly");
if (e.sh && !C.allowSharedWrites) return fail("err_shared");
const base = LEARN.byKey[key];
if (!base) return fail("err_unseen");
const disc = LEARN.disc[base] || {};
const S = global.get(C.contextName) || { state: {} };
const v = msg.payload;
const kind = base.split("/").slice(-2)[0];

function onOff(x) {
    if (typeof x === "string") {
        const s = x.trim().toLowerCase();
        if (s === "toggle") return "TOGGLE";
        if (["on", "true", "1"].includes(s)) return "ON";
        if (["off", "false", "0"].includes(s)) return "OFF";
        return null;
    }
    if (typeof x === "boolean" || typeof x === "number") return x ? "ON" : "OFF";
    return null;
}

let payload;
switch (kind) {
    case "button":
        payload = "PRESS";
        break;
    case "switch":
        payload = onOff(v);
        if (!payload) return fail("err_value", { value: JSON.stringify(v) });
        break;
    case "light": {
        if (v && typeof v === "object") { payload = JSON.stringify(v); break; }
        let s = onOff(v);
        if (!s) return fail("err_value", { value: JSON.stringify(v) });
        if (s === "TOGGLE") s = S.state[key] ? "OFF" : "ON";
        payload = JSON.stringify({ state: s });
        break;
    }
    case "number": {
        const n = Number(v);
        const min = disc.min !== undefined ? disc.min : e.min;
        const max = disc.max !== undefined ? disc.max : e.max;
        if (v === "" || v === null || !Number.isFinite(n)) return fail("err_value", { value: JSON.stringify(v) });
        if ((min !== undefined && n < min) || (max !== undefined && n > max)) return fail("err_range", { min, max });
        payload = String(n);
        break;
    }
    case "select": {
        // the bridge expects the option text in its own language: take it from discovery, else from the table
        const current = disc.options || (e.o ? optionList(e.o[0], LEARN.lang || "en") : null);
        let index = null;
        if (typeof v === "number" || (typeof v === "string" && /^\d+$/.test(v.trim()))) index = Number(v);
        else if (typeof v === "string") {
            const hit = e.o ? optionIndex(e, v) : null;
            if (hit) index = hit.index;
            else if (current && current.includes(v)) { payload = v; break; }
        }
        if (index === null || !current || !current[index]) return fail("err_option", { value: JSON.stringify(v) });
        payload = current[index];
        break;
    }
    case "time": {
        let h, m, s = 0;
        if (v && typeof v === "object") { h = v.hour; m = v.minute; s = v.second || 0; }
        else {
            const r = /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/.exec(String(v).trim());
            if (r) { h = +r[1]; m = +r[2]; s = +(r[3] || 0); }
        }
        if (!(h >= 0 && h < 24 && m >= 0 && m < 60)) return fail("err_value", { value: JSON.stringify(v) });
        payload = JSON.stringify({ hour: h, minute: m, second: s });
        break;
    }
    default:  // text
        if (v === undefined || v === null || typeof v === "object") return fail("err_value", { value: JSON.stringify(v) });
        payload = String(v);
}
node.status({ fill: "green", shape: "dot", text: t("st_sent", { key }) });
return { topic: `${base}/command`, payload, qos: 0, retain: false };

// Every state is in global context, from any tab:
const aq = global.get("aquaclean");
msg.payload = {
    online: aq.online,
    seated: aq.state.seated,
    waterTemperature: aq.state.water_temperature,
    lightColor: aq.label.light_color   // the option text in your language
};
return msg;
